export function analyzeStructure(p){if(!Array.isArray(p.sections)||!Array.isArray(p.tracks)||!Number.isFinite(p.bars)||p.bars<=0)throw Error('Structure invalide');let cursor=0;const warnings=[];const sections=p.sections.map(s=>{if(!Number.isFinite(s.start)||!Number.isFinite(s.length)||s.start<0||s.length<=0)throw Error('Section invalide');if(s.start!==cursor)warnings.push('Discontinuité : '+s.name);cursor=s.start+s.length;const from=s.start*16,to=cursor*16;let notes=0,hits=0,audioClips=0;for(const t of p.tracks){if(t.mute)continue;for(const c of t.clips||[]){if(c.muted||!Number.isFinite(c.start))continue;const offset=c.start*16;for(const n of c.notes||[])if(!n.muted&&Number.isFinite(n.step)&&offset+n.step>=from&&offset+n.step<to)notes++;for(const row of Object.values(c.pattern||{}))if(Array.isArray(row))row.forEach((v,i)=>{if(v>0&&offset+i>=from&&offset+i<to)hits++});if(t.type==='audio'&&c.start<cursor&&c.start+c.length>s.start)audioClips++;}}return {name:s.name,start:s.start,bars:s.length,notes,hits,audioClips,eventsPerBar:(notes+hits)/s.length};});if(cursor!==p.bars)warnings.push('Durée incohérente');const contrasts=sections.slice(1).map((s,i)=>({from:sections[i].name,to:s.name,densityDelta:s.eventsPerBar-sections[i].eventsPerBar}));return {sections,contrasts,warnings,limitation:'Densité des événements, pas qualité perceptive; audio non transcrit.'};}